const active=flow.get('probe_active');
if(active && Date.now()-active.started<10000) return [null,null,{payload:{evento:'DBS_PRUEBA_OCUPADA'}}];
const run=Date.now();
flow.set('probe_active',{run,started:run,bytes:0,chunks:0,raw:''});
msg.probe_run=run;
msg.payload=Buffer.from('0,172.16.0.144','ascii');
return [msg,{probe_run:run,payload:null},{payload:{evento:'DBS_SOLICITUD_PREPARADA',host:'10.1.0.105',port:5000,ip:'172.16.0.144',tipo:'0',bytes_solicitud:msg.payload.length,terminador_solicitud:'ninguno'}}];

const state=flow.get('probe_active');
if(!state || state.run!==msg.probe_run) return null;
const chunk=Buffer.isBuffer(msg.payload)?msg.payload:Buffer.from(String(msg.payload??''),'utf8');
state.bytes+=chunk.length; state.chunks+=1;
if(state.bytes>8192){flow.set('probe_active',null);return {payload:{evento:'DBS_RESPUESTA_EXCESIVA',bytes:state.bytes}};}
state.raw+=chunk.toString('utf8');
const end=state.raw.indexOf('*');
const result={evento:end>=0?'DBS_RESPUESTA_COMPLETA':'DBS_BLOQUE_RECIBIDO',bytes_acumulados:state.bytes,bloques:state.chunks,terminador:end>=0};
if(end>=0){const fields=state.raw.slice(0,end).split(',');result.firma=fields[0];result.ip=fields[1]||null;result.campos=fields.length;result.valida_tipo_0=fields[0]==='~'&&fields[1]==='172.16.0.144'&&fields.length===86;flow.set('probe_active',null);}
else flow.set('probe_active',state);
return {payload:result};

const state=flow.get('probe_active');
const same=state&&state.run===msg.probe_run;
if(same) flow.set('probe_active',null);
const connected=flow.get('probe_connected')===true;
if(connected) flow.set('probe_connected',false);
return [connected?{reset:true}:null,{payload:{evento:same?(state.bytes?'DBS_RESPUESTA_INCOMPLETA':'DBS_SIN_BYTES_8S'):'DBS_PRUEBA_FINALIZADA',bytes:same?state.bytes:null,bloques:same?state.chunks:null,conexion_ya_cerrada:!connected}}];
